      hu: ["Hundested", "sarkkutató", "múzeum", "történelmi örökség"],
      ro: ["Hundested", "explorator polar", "muzeu", "patrimoniu istoric"],
      en: ["Hundested", "Polar explorer", "Museum", "Historic legacy"],
